    out={k:r.get(k) for k in ['step','reward','reward_std','eval_reward','eval_reward_std','loss','grad_norm','learning_rate','step_time','eval_runtime','completions/mean_length','eval_completions/mean_length','tools/call_frequency','eval_tools/call_frequency'] if k in r}
