print('\n=== rollouts summary ===')
rewards=[]
by_case=collections.Counter()
by_case_reward=collections.defaultdict(list)
with open('observed_run/rollouts.jsonl') as f:
    for i,line in enumerate(f):
        obj=json.loads(line)
        r=obj.get('reward')
        if r is not None: rewards.append(r)
        case=obj.get('case_id')
        if case: by_case[case]+=1; by_case_reward[case].append(r)
        if i<3:
            print('sample', i, {k: obj.get(k) for k in ['trajectory_id','case_id','reward','done','truncated','source_sha256']})
            for k in ['messages','tool_events','result','info']:
                if k in obj:
                    s=json.dumps(obj[k])
                    print(k, s[:1200])
print('num_rollouts', len(rewards), 'reward_values', collections.Counter(rewards))
for case,count in by_case.items():
    vals=by_case_reward[case]
    print('case', case, 'n', count, 'mean_reward', sum(vals)/len(vals), 'values', collections.Counter(vals))
