import json, collections
print('===== GRADE SUMMARY FROM TOOL TRACES =====')
grades=[]
with open('observed_run/tool_traces.jsonl') as f:
    for line in f:
        obj=json.loads(line)
        if obj.get('event')=='grade':
            grades.append(obj)
print('num_grade_events', len(grades))
for g in grades[:5]:
    print(json.dumps(g)[:1500])
